<script setup>
import { ref } from 'vue';
const expression = ref(''), answer = ref('');
function calculate() { try { if (!/^[0-9+*/().\s-]+$/.test(expression.value)) throw Error(); const tokens = expression.value.match(/\d+(?:\.\d+)?|[()+*/-]/g); if (!tokens || tokens.join('') !== expression.value.replace(/\s/g,'')) throw Error(); let index=0; function factor(){const token=tokens[index++];if(token==='('){const result=sum();if(tokens[index++]!==')')throw Error();return result;}if(token==='-')return -factor();if(!/^\d/.test(token || ''))throw Error();return Number(token);}function product(){let result=factor();while(tokens[index]==='*'||tokens[index]==='/'){const op=tokens[index++];const value=factor();result=op==='*'?result*value:result/value;}return result;}function sum(){let result=product();while(tokens[index]==='+'||tokens[index]==='-'){const op=tokens[index++];result+= (op==='+'?1:-1)*product();}return result;}const result=sum();if(index!==tokens.length||!Number.isFinite(result))throw Error();answer.value=String(result);}catch{answer.value='表达式无效';} }
</script>
<template><section class="calculator"><input v-model="expression" aria-label="计算表达式" placeholder="0" @keyup.enter="calculate"/><output>{{ answer }}</output><div><button v-for="key in ['7','8','9','/','4','5','6','*','1','2','3','-','0','.','(',')','C','+','=','⌫']" :key="key" @click="key==='='?calculate():key==='C'?(expression='',answer=''):key==='⌫'?expression=expression.slice(0,-1):expression+=key">{{ key }}</button></div></section></template>
<style scoped>.calculator{padding:25px}.calculator input{width:100%;font-size:26px;text-align:right}.calculator output{display:block;min-height:45px;text-align:right;font-size:22px;margin:12px 0}.calculator>div{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.calculator button{height:52px;border:1px solid #dce3df;background:white;border-radius:5px;font-size:18px}</style>
